from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA = ROOT / "data" / "cha_questions.json"


def q(question_id, subject, source, stem, options, correct, explanation, stem_hi=None, options_hi=None, explanation_hi=None):
    return {
        "id": question_id,
        "subject": subject,
        "source": source,
        "stem": stem,
        "stemHi": stem_hi or stem,
        "options": options,
        "optionsHi": options_hi or options,
        "correctIndex": correct,
        "explanation": explanation,
        "explanationHi": explanation_hi or explanation,
    }


