# Keep the data file reproducible and enforce invariants before writing it.
seen_ids = set()
seen_stems = set()
for item in QUESTIONS:
    if item["id"] in seen_ids:
        raise ValueError(f"Duplicate id: {item['id']}")
    seen_ids.add(item["id"])
    stem_key = " ".join(item["stem"].lower().split())
    if stem_key in seen_stems:
        raise ValueError(f"Duplicate stem: {item['stem']}")
    seen_stems.add(stem_key)
    if len(item["options"]) != len(item["optionsHi"]):
        raise ValueError(f"Hindi option mismatch: {item['id']}")
    if not 0 <= item["correctIndex"] < len(item["options"]):
        raise ValueError(f"Invalid correct index: {item['id']}")

DATA.write_text(json.dumps(QUESTIONS, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"Wrote {len(QUESTIONS)} distinct CHA questions")
